en = {
    GUIDE_BTN_TOOLTIP = "Forever guide (3 pages)",
    GUIDE_PAGE1_TITLE = "Getting started", GUIDE_PAGE2_TITLE = "Captures and resources",
    GUIDE_PAGE3_TITLE = "Keeps, outposts and rankings",
    GUIDE_SECTION_TRAVEL = "Enter the open world",
    GUIDE_TRAVEL_ALLIANCE = "Travel to an Overlord front in the open world. Check the map for available capture points and follow the Next objective arrow.",
    GUIDE_SECTION_SHARD = "Layers and synchronization",
    GUIDE_SHARD_BODY = "Overlord shares captures and rankings within your NA/EU region through the addon channel, groups and Battle.net relays. Keep the addon updated and group with allies for faster updates.\n\nA layer is the copy of the open world you are in. Group with allies to fight on the same layer. For a Guild Keep assault, follow the layer contact shown by Overlord to join the ongoing fight.",
    GUIDE_SECTION_PROGRESS = "The seven war fronts",
    GUIDE_PROGRESS_BODY = "Arathi Highlands, Loch Modan, Durotar, Ashenvale, Elwynn Forest and Redridge Mountains each have their own capture path and faction capitals. Capture an available point after its prerequisites are held; several branches can be open at once. The special Hillsbrad front has only two large town circles: Southshore and Tarren Mill.\n\nOpen-world honorable kills at any level count from Blizzard's official honorable-kill counter, once per credit. The featured front grants +1 coin per honorable kill.",
    GUIDE_SECTION_PANEL = "The Overlord panel",
    GUIDE_PANEL_BODY = "Open the panel with the minimap button or /ov. Choose a front to see control points, current capture, recent activity, weekly domination and the leaderboard. The side tab shows the featured front and recent fighting.\n\nThe top HUD shows coins, wood and keep actions near their locations. Auto mode is the default; the book can be shown in Options. Reopen this guide from the panel or with /ov guide.",
    GUIDE_SECTION_OPTIONS = "Useful options",
    GUIDE_OPTIONS_BODY = "Use the panel's Options button or Escape → AddOns → Overlord. Adjust the automatic objective pin, map and minimap overlays, sounds, panel scale and top HUD. /ov hud auto shows useful panels near objectives; /ov hud on keeps them visible on relevant maps.",
    GUIDE_SECTION_FEATURED = "Featured front",
    GUIDE_FEATURED_BODY = "The featured front changes daily. Each official open-world honorable kill there gives +1 Overlord coin. The leaderboard records the kill only once. Weekly rankings reset on Tuesday at 08:00 UTC during the Forever beta.",
    GUIDE_SECTION_CONTEST = "Capture and contest",
    GUIDE_CONTEST_BODY = "Normal points require 2 minutes inside the capture circle. Leaving makes progress decay. Equal numbers of opponents freeze progress; enemy superiority pushes it back. A hostile capital takes 8 minutes, your own capital 2 minutes. A complete front victory gives +2% weekly domination and a 15-minute truce.",
    GUIDE_SECTION_GOLD = "Coin mines",
    GUIDE_GOLD_BODY = "Mines on the map:\n%s\n\nInside a mine circle, gain 1 coin every 3 seconds (personal cap 100); mining an ore node grants 5. Spend 25 coins on an attack that shortens your next capture by 60 seconds, or a reinforcement that adds 60 seconds to the next enemy capture of one of your front points. Shared mine stock refills over time.",
    GUIDE_SECTION_WOOD = "Forests",
    GUIDE_WOOD_BODY = "Forests on the map:\n%s\n\nInside a forest circle, gain 1 wood every 15 seconds (personal cap 500). Each forest has shared faction stock of 100 that refills over time. Spend 250 wood for +1% weekly domination for your faction.",
    GUIDE_SECTION_SIEGE = "Capital victory",
    GUIDE_SIEGE_BODY = "Follow the front's prerequisites to assault its enemy capital. Capturing it wins the front, grants +2% weekly domination and starts a 15-minute truce. Your faction recaptures its own capital with the normal 2-minute timer.",
    GUIDE_SECTION_GUILD_KEEP = "Guild Keeps",
    GUIDE_GUILD_KEEP_BODY = "Guild Keeps stand in Stonetalon Mountains, Wetlands, Badlands, the Crossroads and Mulgore.\n\nIcons: %s\n\nYou need a guild. Sieges open at %s; outside these windows, capture is closed. Hold the square for %d minutes. Leaving makes progress decay; equal enemy numbers freeze it and enemy superiority pushes it back. Only the opposing faction can contest or reclaim. Follow the assault's anchored layer contact.\n\nAt %s, capture or successful defense gives the holder one siege win. The keep remains with its guild until an enemy capture or weekly reset. Leaderboard kills at a keep count only inside its square during the siege hour.",
    GUIDE_SECTION_OUTPOST = "Guild outposts",
    GUIDE_OUTPOST_BODY = "The six regular fronts have a guild outpost each. The two-point Southshore / Tarren Mill front has none. Savix Chapel in Silverpine Forest and Aeythyr Lodge in the Eastern Plaguelands are additional outdoor outposts. Outposts are open at all times. A guild member holds the square for 5 minutes. Only the opposing faction can contest or reclaim it. While held, enemy captures on ordinary points of that front take 30 seconds longer. Ownership lasts until enemy capture or weekly reset.",
    GUIDE_SECTION_FACTION_CALL = "Call to arms and command",
    GUIDE_FACTION_CALL_BODY = "On an active front with enemies nearby, Call to arms alerts reachable allies through Forever's sync bridges. A party or raid leader can take the Commandant role: their position appears to synced allies on the map.",
    GUIDE_SECTION_TOOLS = "Rankings and sync",
    GUIDE_TOOLS_BODY = "The weekly leaderboard shows official open-world honorable kills, captures, guild keeps and outposts. Open it from the panel or with /ov lb. /ov sync requests a catch-up from reachable players. Gold contracts use full Forever names and manual mail/COD settlement. The Hall of Fame opens from Actions."
},
fr = {
    GUIDE_BTN_TOOLTIP = "Guide Forever (3 pages)",
    GUIDE_PAGE1_TITLE = "Premiers pas", GUIDE_PAGE2_TITLE = "Captures et ressources",
