},
de = {
    GUIDE_BTN_TOOLTIP = "Forever-Anleitung (3 Seiten)",
    GUIDE_PAGE1_TITLE = "Erste Schritte", GUIDE_PAGE2_TITLE = "Eroberung und Ressourcen",
    GUIDE_PAGE3_TITLE = "Festungen, Außenposten und Rangliste",
    GUIDE_SECTION_TRAVEL = "In die offene Welt",
    GUIDE_TRAVEL_ALLIANCE = "Reist zu einer Overlord-Front in der offenen Welt. Prüft die Karte auf verfügbare Punkte und folgt dem Pfeil zum nächsten Ziel.",
    GUIDE_SECTION_SHARD = "Layer und Synchronisierung",
    GUIDE_SHARD_BODY = "Overlord teilt Eroberungen und Ranglisten innerhalb eurer NA/EU-Region über Addon-Kanal, Gruppen und Battle.net-Relays. Haltet das Addon aktuell und bildet Gruppen für schnellere Updates.\n\nEin Layer ist eine Kopie der offenen Welt. Bildet eine Gruppe, um auf demselben Layer zu kämpfen. Folgt bei einem Gildenfestungsangriff dem von Overlord angezeigten Layer-Kontakt, um am laufenden Kampf teilzunehmen.",
    GUIDE_SECTION_PROGRESS = "Die sieben Fronten",
    GUIDE_PROGRESS_BODY = "Arathihochland, Loch Modan, Durotar, Eschental, Wald von Elwynn und Rotkammgebirge haben eigene Eroberungswege und Fraktionshauptstädte. Nehmt verfügbare Punkte nach Erfüllung ihrer Voraussetzungen ein; mehrere Zweige können offen sein. Die besondere Hügellandfront hat nur zwei große Ortskreise: Süderstade und Tarrens Mühle.\n\nEhrenhafte Siege in der offenen Welt zählen auf jeder Stufe nach Blizzards offiziellem Zähler, einmal pro Gutschrift. Die Front des Tages gewährt +1 Coin pro ehrenhaftem Sieg.",
    GUIDE_SECTION_PANEL = "Overlord-Panel",
    GUIDE_PANEL_BODY = "Öffnet das Panel über die Minikarten-Schaltfläche oder /ov. Wählt eine Front für Kontrollpunkte, laufende Eroberung, jüngste Aktivität, wöchentliche Dominanz und Rangliste. Der Seitenreiter zeigt die Front des Tages und jüngste Kämpfe.\n\nDas obere HUD zeigt Coins, Holz und Festungsaktionen am jeweiligen Ort. Auto ist voreingestellt; das Buch lässt sich in den Optionen einblenden. Öffnet die Anleitung im Panel oder mit /ov guide erneut.",
    GUIDE_SECTION_OPTIONS = "Nützliche Optionen",
    GUIDE_OPTIONS_BODY = "Optionen findet ihr im Panel oder unter Escape → AddOns → Overlord. Stellt automatische Zielmarkierung, Karten- und Minikarten-Overlays, Töne, Panelgröße und oberes HUD ein. /ov hud auto zeigt passende Panels nahe Zielen; /ov hud on hält sie auf den jeweiligen Karten sichtbar.",
    GUIDE_SECTION_FEATURED = "Front des Tages",
    GUIDE_FEATURED_BODY = "Die hervorgehobene Front wechselt täglich. Jeder offizielle ehrenhafte Sieg in der offenen Welt dort bringt +1 Overlord-Coin; die Rangliste zählt ihn nur einmal. In der Forever-Beta wird die Wochenrangliste dienstags um 08:00 UTC zurückgesetzt.",
    GUIDE_SECTION_CONTEST = "Eroberung und Gegenwehr",
    GUIDE_CONTEST_BODY = "Ein normaler Punkt braucht 2 Minuten im Kreis. Beim Verlassen sinkt der Fortschritt. Gleich viele Gegner stoppen ihn; gegnerische Überzahl drängt ihn zurück. Die feindliche Hauptstadt braucht 8 Minuten, die eigene 2. Ein vollständiger Frontsieg gibt +2 % Wochendominanz und 15 Minuten Waffenruhe.",
    GUIDE_SECTION_GOLD = "Coin-Minen",
    GUIDE_GOLD_BODY = "Minen auf der Karte:\n%s\n\nIm Kreis gibt es alle 3 Sekunden 1 Coin (persönliches Maximum 100); ein Erzvorkommen gibt 5. Gebt 25 Coins aus, um die nächste Eroberung um 60 Sekunden zu verkürzen oder die nächste feindliche Eroberung eines eurer Punkte um 60 Sekunden zu verlängern. Gemeinsame Vorräte füllen sich wieder auf.",
    GUIDE_SECTION_WOOD = "Wälder",
    GUIDE_WOOD_BODY = "Wälder auf der Karte:\n%s\n\nIm Kreis erhaltet ihr alle 15 Sekunden 1 Holz (persönliches Maximum 500). Jeder Wald hat einen gemeinsamen Fraktionsvorrat von 100, der sich auffüllt. 250 Holz geben eurer Fraktion +1 % Wochendominanz.",
    GUIDE_SECTION_SIEGE = "Sieg an der Hauptstadt",
    GUIDE_SIEGE_BODY = "Erfüllt die Frontvoraussetzungen und greift die feindliche Hauptstadt an. Ihre Eroberung gewinnt die Front, gibt +2 % Wochendominanz und startet 15 Minuten Waffenruhe. Eure eigene Hauptstadt erobert ihr mit dem normalen 2-Minuten-Timer zurück.",
    GUIDE_SECTION_GUILD_KEEP = "Gildenfestungen",
    GUIDE_GUILD_KEEP_BODY = "Gildenfestungen stehen im Steinkrallengebirge, Sumpfland, Ödland, am Wegekreuz und in Mulgore.\n\nSymbole: %s\n\nIhr braucht eine Gilde. Belagerungen öffnen um %s; sonst ist die Eroberung gesperrt. Haltet das Quadrat %d Minuten. Verlassen senkt den Fortschritt; gleich viele Gegner stoppen ihn, Überzahl drängt ihn zurück. Nur die Gegenfraktion kann angreifen oder zurückerobern. Folgt dem Kontakt des verankerten Layers.\n\nUm %s bringt Eroberung oder erfolgreiche Verteidigung dem Besitzer einen Belagerungssieg. Die Festung bleibt bis zur feindlichen Eroberung oder zum Wochenreset. Ranglistensiege zählen dort nur im Quadrat während der Belagerungsstunde.",
    GUIDE_SECTION_OUTPOST = "Gilden-Außenposten",
    GUIDE_OUTPOST_BODY = "Die sechs regulären Fronten haben je einen Außenposten. Die Front mit zwei Punkten Süderstade / Tarrens Mühle hat keinen. Die Savix-Kapelle im Silberwald und die Aeythyr Lodge in den Östlichen Pestländern sind weitere Außenposten. Sie sind immer offen. Ein Gildenmitglied hält das Quadrat 5 Minuten. Nur die Gegenfraktion kann angreifen oder zurückerobern. Solange er gehalten wird, dauern gegnerische Eroberungen normaler Frontpunkte 30 Sekunden länger. Er bleibt bis zur feindlichen Eroberung oder zum Wochenreset.",
    GUIDE_SECTION_FACTION_CALL = "Ruf und Kommando",
    GUIDE_FACTION_CALL_BODY = "An einer aktiven Front mit nahen Feinden warnt der Ruf zu den Waffen erreichbare Verbündete über Forevers Sync-Brücken. Ein Gruppen- oder Schlachtzugleiter kann Kommandant werden und erscheint auf der Karte synchronisierter Verbündeter.",
    GUIDE_SECTION_TOOLS = "Rangliste und Sync",
